use crate::*;
use anyhow::Context;
use rusqlite::{Connection, OptionalExtension, params};
use std::path::Path;
use std::time::{SystemTime, UNIX_EPOCH};

pub struct IndexStore {
    connection: Connection,
}

fn compatible_cache_schema(connection: &Connection) -> Result<bool> {
    // These are the exact schemas generated by the original unversioned cache.
    // Table names alone do not establish ownership of an existing database.
    let schemas = [
        (
            "metadata",
            "CREATE TABLE metadata (key TEXT PRIMARY KEY, value TEXT NOT NULL)",
            vec![("key", "TEXT", 0, 1), ("value", "TEXT", 1, 0)],
        ),
        (
            "graphs",
            "CREATE TABLE graphs (id INTEGER PRIMARY KEY CHECK(id=1), json TEXT NOT NULL)",
            vec![("id", "INTEGER", 0, 1), ("json", "TEXT", 1, 0)],
        ),
        (
            "files",
            "CREATE TABLE files (path TEXT PRIMARY KEY, hash TEXT NOT NULL, json TEXT NOT NULL)",
            vec![
                ("path", "TEXT", 0, 1),
                ("hash", "TEXT", 1, 0),
                ("json", "TEXT", 1, 0),
            ],
        ),
        (
            "proposals",
            "CREATE TABLE proposals (id TEXT PRIMARY KEY, json TEXT NOT NULL)",
            vec![("id", "TEXT", 0, 1), ("json", "TEXT", 1, 0)],
        ),
    ];
    let normalize = |value: &str| {
        value
            .split_whitespace()
            .collect::<String>()
            .to_ascii_lowercase()
            .replace("createtableifnotexists", "createtable")
            .trim_end_matches(';')
            .to_owned()
    };
    let extra: i64 = connection.query_row(
        "SELECT COUNT(*) FROM sqlite_schema WHERE type!='table' AND name NOT GLOB 'sqlite_*'",
        [],
        |r| r.get(0),
    )?;
    if extra != 0 {
        return Ok(false);
    }
    for (name, expected_sql, expected_columns) in schemas {
        let sql: Option<String> = connection.query_row(
            "SELECT sql FROM sqlite_schema WHERE type='table' AND name=?1",
            [name],
            |row| row.get(0),
        )?;
        if sql.is_none_or(|sql| normalize(&sql) != normalize(expected_sql)) {
            return Ok(false);
        }
        let columns: Vec<(String, String, i64, Option<String>, i64)> = {
            let mut query = connection.prepare(&format!("PRAGMA table_info({name})"))?;
            query
                .query_map([], |row| {
                    Ok((
                        row.get(1)?,
                        row.get(2)?,
                        row.get(3)?,
                        row.get(4)?,
                        row.get(5)?,
                    ))
                })?
                .collect::<rusqlite::Result<_>>()?
        };
        if columns.len() != expected_columns.len() {
            return Ok(false);
        }
        for (
            (actual_name, actual_type, not_null, default_value, primary_key),
            (name, data_type, required, key),
        ) in columns.into_iter().zip(expected_columns)
        {
            if actual_name != name
                || actual_type.to_ascii_uppercase() != data_type
                || not_null != required
                || default_value.is_some()
                || primary_key != key
            {
                return Ok(false);
            }
        }
    }
    Ok(true)
}

impl IndexStore {
    pub fn open(path: &Path) -> Result<Self> {
        ensure_no_symlinks(path)?;
        if path.exists() && std::fs::symlink_metadata(path)?.file_type().is_symlink() {
            bail!("cache cannot be a symbolic link");
        }
        if let Some(parent) = path.parent().filter(|p| !p.as_os_str().is_empty()) {
            std::fs::create_dir_all(parent)?;
        }
        let connection = Connection::open(path).context("cannot open index cache")?;
        connection.busy_timeout(std::time::Duration::from_secs(10))?;
        const APPLICATION_ID: i64 = 0x474c5950;
        let application: i64 =
            connection.query_row("PRAGMA application_id", [], |row| row.get(0))?;
        let tables: BTreeSet<String> = {
            let mut query = connection.prepare(
                "SELECT name FROM sqlite_schema WHERE type='table' AND name NOT GLOB 'sqlite_*'",
            )?;
            query
                .query_map([], |row| row.get(0))?
                .collect::<rusqlite::Result<_>>()?
        };
        let expected: BTreeSet<_> = ["metadata", "graphs", "files", "proposals"]
            .into_iter()
            .map(String::from)
            .collect();
        if (application != 0 && application != APPLICATION_ID)
            || (!tables.is_empty() && tables != expected)
        {
            bail!("index is not an empty database or a compatible Glyphibe cache");
        }
        if !tables.is_empty() && !compatible_cache_schema(&connection)? {
            bail!("existing database schema is not a compatible Glyphibe cache");
        }
        connection.execute_batch("PRAGMA journal_mode=WAL; PRAGMA trusted_schema=OFF;
            CREATE TABLE IF NOT EXISTS metadata (key TEXT PRIMARY KEY, value TEXT NOT NULL);
            CREATE TABLE IF NOT EXISTS graphs (id INTEGER PRIMARY KEY CHECK(id=1), json TEXT NOT NULL);
            CREATE TABLE IF NOT EXISTS files (path TEXT PRIMARY KEY, hash TEXT NOT NULL, json TEXT NOT NULL);
            CREATE TABLE IF NOT EXISTS proposals (id TEXT PRIMARY KEY, json TEXT NOT NULL);")?;
        connection.pragma_update(None, "application_id", APPLICATION_ID)?;
        Ok(Self { connection })
    }
    pub fn bind_repository(&self, root: &Path) -> Result<()> {
        let canonical = root.canonicalize()?;
        let identity = fingerprint(&canonical.to_string_lossy());
        let existing: Option<String> = self
            .connection
            .query_row(
                "SELECT value FROM metadata WHERE key='repository'",
                [],
                |r| r.get(0),
            )
            .optional()?;
        if existing.is_some_and(|v| v != identity) {
            bail!("cache belongs to another repository");
        }
        self.connection.execute(
            "INSERT OR IGNORE INTO metadata(key,value) VALUES('repository',?1)",
            [identity],
        )?;
        Ok(())
    }
    pub fn load_graph(&self) -> Result<Option<Graph>> {
        let json: Option<String> = self
            .connection
            .query_row("SELECT json FROM graphs WHERE id=1", [], |r| r.get(0))
            .optional()?;
        json.map(|j| {
            let graph: Graph = serde_json::from_str(&j)?;
            graph.validate()?;
            Ok(graph)
        })
        .transpose()
    }
    pub fn save_graph(&self, graph: &Graph) -> Result<()> {
        graph.validate()?;
        self.connection.execute("INSERT INTO graphs(id,json) VALUES(1,?1) ON CONFLICT(id) DO UPDATE SET json=excluded.json", [serde_json::to_string(graph)?])?;
        Ok(())
    }
    pub fn load_file(&self, path: &str, hash: &str) -> Result<Option<String>> {
        Ok(self
            .connection
            .query_row(
                "SELECT json FROM files WHERE path=?1 AND hash=?2",
                params![path, hash],
                |r| r.get(0),
            )
            .optional()?)
    }
    pub fn save_file(&self, path: &str, hash: &str, json: &str) -> Result<()> {
        self.connection.execute("INSERT INTO files(path,hash,json) VALUES(?1,?2,?3) ON CONFLICT(path) DO UPDATE SET hash=excluded.hash,json=excluded.json", params![path, hash, json])?;
        Ok(())
    }
    pub fn prune_files(&self, paths: &BTreeSet<String>) -> Result<usize> {
        let mut statement = self.connection.prepare("SELECT path FROM files")?;
        let cached: Vec<String> = statement
            .query_map([], |r| r.get(0))?
            .collect::<rusqlite::Result<_>>()?;
        let stale: Vec<_> = cached.into_iter().filter(|p| !paths.contains(p)).collect();
        for path in &stale {
            self.connection
                .execute("DELETE FROM files WHERE path=?1", [path])?;
        }
        Ok(stale.len())
    }
    pub fn propose(
        &self,
        graph: &Graph,
        source: &str,
        target: &str,
        relation: Relation,
        label: &str,
        rationale: &str,
    ) -> Result<Proposal> {
        if !graph.nodes.contains_key(source) || !graph.nodes.contains_key(target) {
            bail!("proposal endpoints must exist");
        }
        if !matches!(
            relation,
            Relation::MapsTo | Relation::HasConcept | Relation::DependsOn
        ) {
            bail!("proposals cannot rewrite observed analysis facts");
        }
        if label.trim().is_empty()
            || label.len() > 200
            || rationale.trim().is_empty()
            || rationale.len() > 8000
        {
            bail!("proposal requires bounded label and rationale");
        }
        if relation == Relation::MapsTo && graph.nodes[source].plane == graph.nodes[target].plane {
            bail!("maps_to proposal must cross planes");
        }
        if relation == Relation::HasConcept && graph.nodes[target].kind != NodeKind::Concept {
            bail!("has_concept requires a concept target");
        }
        let created_at = SystemTime::now().duration_since(UNIX_EPOCH)?.as_secs();
        let proposal = Proposal {
            id: stable_id(&[
                &graph.repository,
                &graph.revision,
                source,
                target,
                &format!("{relation:?}"),
                label,
                rationale,
            ]),
            repository: graph.repository.clone(),
            revision: graph.revision.clone(),
            source: source.into(),
            target: target.into(),
            relation,
            label: label.into(),
            rationale: rationale.into(),
            evidence: EvidenceKind::Proposed,
            created_at,
            status: "pending".into(),
        };
        self.connection.execute(
            "INSERT OR IGNORE INTO proposals(id,json) VALUES(?1,?2)",
            params![proposal.id, serde_json::to_string(&proposal)?],
        )?;
        Ok(proposal)
    }
    pub fn proposals(&self) -> Result<Vec<Proposal>> {
        let mut statement = self
            .connection
            .prepare("SELECT json FROM proposals ORDER BY id")?;
        let jsons = statement.query_map([], |r| r.get::<_, String>(0))?;
        jsons.map(|j| Ok(serde_json::from_str(&j?)?)).collect()
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Proposal {
    pub id: String,
    pub repository: String,
    pub revision: String,
    pub source: String,
    pub target: String,
    pub relation: Relation,
    pub label: String,
    pub rationale: String,
    pub evidence: EvidenceKind,
    pub created_at: u64,
    pub status: String,
}
